TAGS = ["[warmly]", "[confident]", "[smiling]", "[upbeat]", "[confident]"]
def texte(p):
    l = [f"{TAGS[i]} {p[k]}" for i, k in enumerate(["acc", "pb", "tr", "pk", "ob"])]
    return "\n".join(l + END)
def mots(t):
    c = re.sub(r'\[[^\]]+\]\s*', '', t)
    return len(re.findall(r"[\wÀ-ÿ'’-]+", c))
if __name__ == "__main__":
    for p in P:
        w = mots(texte(p)); print(p["n"], w, round(w / 2.76, 1))
    json.dump({p["n"]: texte(p) for p in P}, open('/home/claude/scripts10/textes3.json', 'w'), ensure_ascii=False, indent=1)
